self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin||u.search)return;const base=new URL('./',self.location).pathname,relative=u.pathname.slice(base.length);if(u.pathname===base||relative==='index.html'){event.respondWith(caches.open(CACHE).then(c=>c.match(new URL('./',self.location))).then(r=>r||fetch(event.request)));return;}if(!relative.startsWith('releases/'))return;event.respondWith(caches.match(event.request).then(r=>r||fetch(event.request)));});
